# Hypothesis: a checker should pick the first matching overload, so Literal[True] and Literal[False] overloads listed before a bool overload narrow the return type, and should split a union argument across overloads.
from typing import Literal, assert_type, overload, reveal_type


@overload
def read(data: bytes, *, text: Literal[True]) -> str: ...


@overload
def read(data: bytes, *, text: Literal[False] = False) -> bytes: ...


@overload
def read(data: str, *, text: bool = True) -> str: ...


def read(data: bytes | str, *, text: bool = False) -> bytes | str:
    if isinstance(data, str):
        return data
    return data.decode() if text else data


@overload
def first[T](items: list[T]) -> T: ...


@overload
def first(items: str) -> str: ...


def first[T](items: list[T] | str) -> T | str:
    return items[0]


def pick(v: list[int] | str) -> int | str:
    return first(v)


def maybe_read(flag: bool) -> None:
    read(b'x', text=flag)  # expect-error


assert_type(read(b'hi', text=True), str)
assert read(b'hi', text=True) == 'hi'
assert_type(read(b'hi'), bytes)
assert read(b'hi') == b'hi'
assert_type(read('hi'), str)

reveal_type(pick)
assert pick([3, 4]) == 3
assert pick('xy') == 'x'
maybe_read(True)

try:
    first(3)  # expect-error
except TypeError:
    int_rejected = True
else:
    int_rejected = False
assert int_rejected
